class MinHeap<T> {
  private items: T[] = [];
  constructor(private compare: (a: T, b: T) => number) {}
  get size(): number { return this.items.length; }
  peek(): T | undefined { return this.items[0]; }
  push(value: T): void {
    const a = this.items; a.push(value);
    let i = a.length - 1;
    while (i > 0) { const p = Math.floor((i - 1) / 2); if (this.compare(a[p], a[i]) <= 0) break; [a[p], a[i]] = [a[i], a[p]]; i = p; }
  }
  pop(): T | undefined {
    const a = this.items;
    if (!a.length) return undefined;
    const first = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last; let i = 0;
      while (2 * i + 1 < a.length) {
        let child = 2 * i + 1;
        if (child + 1 < a.length && this.compare(a[child + 1], a[child]) < 0) child++;
        if (this.compare(a[i], a[child]) <= 0) break;
        [a[i], a[child]] = [a[child], a[i]]; i = child;
      }
    }
    return first;
  }
}

export function shortestPath(graph: Map<string, Array<[string, number]>>, start: string, target: string): number {
  const dist = new Map<string, number>([[start, 0]]);
  const heap = new MinHeap<[number, string]>((a, b) => a[0] - b[0]);
  heap.push([0, start]);
  while (heap.size) {
    const [cost, node] = heap.pop()!;
    if (node === target) return cost;
    if (cost !== dist.get(node)) continue;
    for (const [next, weight] of graph.get(node) ?? []) {
      const newCost = cost + weight;
      if (newCost < (dist.get(next) ?? Infinity)) { dist.set(next, newCost); heap.push([newCost, next]); }
    }
  }
  return -1;
}

