def shortest_path(graph, start, target):
    nodes = {start, target, *graph}
    for edges in graph.values():
        nodes.update(v for v, _ in edges)
    dist = {start: 0}
    for _ in range(len(nodes) - 1):
        changed = False
        for u, edges in graph.items():
            for v, weight in edges:
                candidate = dist.get(u, float('inf')) + weight
                if candidate < dist.get(v, float('inf')):
                    dist[v] = candidate
                    changed = True
        if not changed:
            break
    return dist.get(target, -1)

