export function shortestPath(graph: Map<string, Array<[string, number]>>, start: string, target: string): number {
  const nodes = new Set([start, target]);
  for (const [u, edges] of graph) { nodes.add(u); for (const [v] of edges) nodes.add(v); }
  const dist = new Map<string, number>([[start, 0]]);
  for (let pass = 1; pass < nodes.size; pass++) {
    let changed = false;
    for (const [u, edges] of graph) for (const [v, weight] of edges) {
      const candidate = (dist.get(u) ?? Infinity) + weight;
      if (candidate < (dist.get(v) ?? Infinity)) { dist.set(v, candidate); changed = true; }
    }
    if (!changed) break;
  }
  return dist.get(target) ?? -1;
}

