int shortestPath(Map<String, List<Edge>> graph, String start, String target) {
  Set<String> nodes = new HashSet<>(List.of(start, target)); nodes.addAll(graph.keySet());
  for (List<Edge> edges : graph.values()) for (Edge edge : edges) nodes.add(edge.to());
  Map<String, Integer> dist = new HashMap<>(); dist.put(start, 0);
  for (int pass = 1; pass < nodes.size(); pass++) {
    boolean changed = false;
    for (var entry : graph.entrySet()) if (dist.containsKey(entry.getKey())) for (Edge edge : entry.getValue()) {
      int candidate = dist.get(entry.getKey()) + edge.weight();
      if (candidate < dist.getOrDefault(edge.to(), Integer.MAX_VALUE)) { dist.put(edge.to(), candidate); changed = true; }
    }
    if (!changed) break;
  }
  return dist.getOrDefault(target, -1);
}
