export function minRoomsSweep(intervals: number[][]): number {
  const starts = intervals.map((x) => x[0]).sort((a, b) => a - b);
  const ends = intervals.map((x) => x[1]).sort((a, b) => a - b);
  let used = 0, best = 0, endIndex = 0;
  for (const start of starts) {
    if (start >= ends[endIndex]) { used -= 1; endIndex += 1; }
    used += 1;
    best = Math.max(best, used);
  }
  return best;
}

