export function countRegions(grid: number[][]): number {
  const rows = grid.length, cols = grid[0].length;
  const seen = new Set<string>();
  function dfs(r: number, c: number): void {
    const key = r + ',' + c;
    if (r < 0 || c < 0 || r === rows || c === cols || grid[r][c] === 0 || seen.has(key)) return;
    seen.add(key);
    dfs(r + 1, c); dfs(r - 1, c); dfs(r, c + 1); dfs(r, c - 1);
  }
  let total = 0;
  for (let r = 0; r < rows; r += 1) for (let c = 0; c < cols; c += 1) if (grid[r][c] === 1 && !seen.has(r + ',' + c)) { total += 1; dfs(r, c); }
  return total;
}

