int countRegions(int[][] grid) {
  boolean[][] seen = new boolean[grid.length][grid[0].length];
  int total = 0;
  for (int r = 0; r < grid.length; r++) for (int c = 0; c < grid[0].length; c++) if (grid[r][c] == 1 && !seen[r][c]) { total++; dfs(grid, seen, r, c); }
  return total;
}
void dfs(int[][] grid, boolean[][] seen, int r, int c) {
  if (r < 0 || c < 0 || r == grid.length || c == grid[0].length || grid[r][c] == 0 || seen[r][c]) return;
  seen[r][c] = true;
  dfs(grid, seen, r + 1, c); dfs(grid, seen, r - 1, c); dfs(grid, seen, r, c + 1); dfs(grid, seen, r, c - 1);
}

